namespace sarif.managers;







using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.program.model.mem;
using ghidra.program.model.mem;

public class MemoryMapBytesFile {

	private OutputStream os;
	private string fileName;
	private int bytesWritten;
	private Memory memory;

	public MemoryMapBytesFile(Program program, string fileName)
    {
		memory = program.getMemory();
		fileName += ".bytes";
		File file = new File(fileName);
		this.fileName = file.getName();
		if (file.exists()) {
			file.delete();
		}
		os = new BufferedOutputStream(new FileOutputStream(file));
	}

	void close()
    {
		os.close();
	}

	public string getFileName() {
		return fileName;
	}

	public int getOffset() {
		return bytesWritten;
	}

	public void writeBytes(AddressRange range)
    {
		try {
			int BUFSIZE = 32 * 1024;
			long size = range.getLength();
			byte[] buf = new byte[(int) Math.min(size, BUFSIZE)];
			Address addr = range.getMinAddress();
			int n = 0;
			while (size > 0) {
				addr = addr.addNoWrap(n);
				n = memory.getBytes(addr, buf);
				os.write(buf, 0, n);
				bytesWritten += n;
				size -= n;
			}
		} catch (AddressOverflowException e) {
			throw new IOException(e.getMessage());
		} catch (MemoryAccessException e) {
			throw new IOException(e.getMessage());
		} catch (IOException e) {
			throw new IOException(e.getMessage());
		}
	}
}
